function serializeTripDraftDate(value) {
  if (!(value instanceof Date) || Number.isNaN(value.getTime())) {
    return null;
  }

  return value.toISOString();
}

function parseTripDraftDate(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const parsed = new Date(value);

  if (Number.isNaN(parsed.getTime())) {
    return null;
  }

  return parsed;
}

function serializeTripDraftLocation(location) {
  if (!location || typeof location !== 'object') {
    return null;
  }

  const latitude = Number(location.latitude);
  const longitude = Number(location.longitude);

  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
    return null;
  }

  return {
    name:
      typeof location.name === 'string' ? location.name : '',
    latitude,
    longitude,
  };
}

function parseTripDraftLocation(value) {
  return serializeTripDraftLocation(value);
}

function isLaboratoryCatalogRecord(record) {
  const rawName =
    typeof record === 'string' ? record : record?.name;
  const normalizedName = String(rawName ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();

  return (
    normalizedName.startsWith('[test]') ||
    normalizedName.startsWith('test') ||
    normalizedName.startsWith('prueba')
  );
}

function isLaboratoryMealService(service) {
  const normalizedNotes = String(service?.notes ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();

  if (!normalizedNotes) {
    return false;
  }

  return (
    normalizedNotes.startsWith('[test]') ||
    normalizedNotes.startsWith('test') ||
    normalizedNotes.startsWith('prueba') ||
    normalizedNotes.includes('no produccion')
  );
}

const TRIP_PACE_OPTIONS = {
  relaxed: {
    maxActivitiesPerDay: 1,
  },
  balanced: {
    maxActivitiesPerDay: 2,
  },
  intense: {
    maxActivitiesPerDay: 3,
  },
};

function normalizeTripPace(value) {
  if (value === 'relaxed' || value === 'balanced' || value === 'intense') {
    return value;
  }

  return 'balanced';
}

function isTourismSlotActivity(activity) {
  if (!activity || typeof activity !== 'object') {
    return false;
  }

  if (
    activity.occupancyType === 'MEAL' ||
    activity.isAutomaticMeal === true ||
    activity.activityType === 'comida'
  ) {
    return false;
  }

  const sourceType = String(activity.sourceType || '').toUpperCase();
  if (
    sourceType === 'ACCOMMODATION_MEAL' ||
    sourceType === 'EXPERIENCE_MEAL'
  ) {
    return false;
  }

  const mealType = String(
    activity.meal_type ?? activity.mealType ?? ''
  )
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();

  if (
    mealType === 'desayuno' ||
    mealType === 'almuerzo' ||
    mealType === 'cena' ||
    mealType === 'breakfast' ||
    mealType === 'lunch' ||
    mealType === 'dinner'
  ) {
    return false;
  }

  const occupancyType = String(activity.occupancyType || '').toUpperCase();
  if (
    occupancyType === 'TRAVEL' ||
    occupancyType === 'TRAVEL_PRE_FIXED' ||
    occupancyType === 'CANDIDATE'
  ) {
    return false;
  }

  return true;
}

function countTourismSlotActivities(activities) {
  if (!Array.isArray(activities)) {
    return 0;
  }

  return activities.filter((activity) => isTourismSlotActivity(activity)).length;
}

// Solo presentación: formato CRC de referencia (sin decimales).
function formatCrcReferenceAmount(value) {
  const amount = Number(value);

  if (!Number.isFinite(amount) || amount < 0) {
    return null;
  }

  try {
    const formatted = new Intl.NumberFormat('es-CR', {
      style: 'currency',
      currency: 'CRC',
      maximumFractionDigits: 0,
      minimumFractionDigits: 0,
    }).format(Math.round(amount));

    if (typeof formatted === 'string' && formatted.trim()) {
      // Preferir símbolo ₡ si Intl devuelve "CRC".
      return formatted.replace(/\bCRC\b/g, '₡').replace(/\s+/g, ' ').trim();
    }
  } catch (error) {
    // Fallback manual es-CR.
  }

  const rounded = Math.round(amount);
  const withSeparators = String(rounded).replace(
    /\B(?=(\d{3})+(?!\d))/g,
    '.'
  );

  return `₡${withSeparators}`;
}

// Solo presentación: "14:00:00" -> "14:00". No modifica el valor original.
function formatTimeHHMM(value) {
  if (value === null || value === undefined) {
    return '';
  }

  const rawValue = String(value).trim();
  const match = rawValue.match(/^(\d{1,2}):(\d{2})(?::\d{2}(?:\.\d+)?)?$/);

  if (!match) {
    return rawValue;
  }

  return `${match[1].padStart(2, '0')}:${match[2]}`;
}

// Agregación fiscal multi-rate (solo presentación de displayRate*).
// No altera displayRateBreakdown ni getTaxInfoFromPricing.
// - taxIncluded: solo true/false reales; mezcla o desconocidos → null
// - taxRate: solo si TODAS las líneas tienen la misma tasa numérica
function aggregateDisplayRateTaxFromItems(items) {
  const list = Array.isArray(items) ? items : [];
  if (list.length === 0) {
    return { taxIncluded: null, taxRate: null };
  }

  let allTrue = true;
  let allFalse = true;
  let anyUnknownIncluded = false;

  list.forEach((item) => {
    const value = item?.taxIncluded;
    if (value === true) {
      allFalse = false;
    } else if (value === false) {
      allTrue = false;
    } else {
      anyUnknownIncluded = true;
      allTrue = false;
      allFalse = false;
    }
  });

  let taxIncluded = null;
  if (!anyUnknownIncluded) {
    if (allTrue) {
      taxIncluded = true;
    } else if (allFalse) {
      taxIncluded = false;
    }
  }

  let taxRate = null;
  const numericRates = [];
  let ratesComplete = true;

  list.forEach((item) => {
    const rawRate = item?.taxRate;
    if (
      rawRate === null ||
      rawRate === undefined ||
      rawRate === ''
    ) {
      ratesComplete = false;
      return;
    }
    const numericRate = Number(rawRate);
    if (!Number.isFinite(numericRate)) {
      ratesComplete = false;
      return;
    }
    numericRates.push(numericRate);
  });

  if (
    ratesComplete &&
    numericRates.length === list.length &&
    numericRates.length > 0
  ) {
    const firstRate = numericRates[0];
    if (numericRates.every((rate) => rate === firstRate)) {
      taxRate = firstRate;
    }
  }

  return { taxIncluded, taxRate };
}

