// Solo presentación: mapea period/mealPeriod persistido a un label
// localizado. No modifica activity.period ni mealPeriod, ni comparaciones
// del scheduler.
function getLocalizedTripPeriod(period, language) {
  const normalizedPeriod = String(period ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();

  switch (normalizedPeriod) {
    case 'manana':
      return translate(language, 'itinerary.period.morning');
    case 'tarde':
      return translate(language, 'itinerary.period.afternoon');
    case 'noche':
      return translate(language, 'itinerary.period.evening');
    case 'desayuno':
      return translate(language, 'itinerary.period.breakfast');
    case 'almuerzo':
      return translate(language, 'itinerary.period.lunch');
    case 'cena':
      return translate(language, 'itinerary.period.dinner');
    default:
      return period;
  }
}

