// Solo presentación: describe días vacíos según su contexto sin alterar el
// itinerario, sus actividades, el hospedaje ni los snapshots persistidos.
function getLocalizedItineraryEmptyDaySubtitle({
  hasTourismActivities,
  hasMeals,
  isFirstItineraryDay,
  isLastItineraryDay,
  hasAccommodation,
  language,
}) {
  if (hasTourismActivities || hasMeals) {
    return null;
  }

  if (!hasAccommodation) {
    return translate(language, 'itinerary.noActivities');
  }

  // Conserva la prioridad actual de llegada para itinerarios de un solo día.
  if (isFirstItineraryDay) {
    return translate(language, 'itinerary.arrivalDay');
  }

  if (isLastItineraryDay) {
    return translate(language, 'itinerary.departureDay');
  }

  return translate(language, 'itinerary.enjoyAccommodation');
}

// Tags de interés que requieren opt-in explícito en tripPreferences.
// `adventure` y categorías generales NO van aquí.
const SPECIALIZED_OPT_IN_INTEREST_TAGS = new Set([
  'mountain_biking',
]);

function getExperienceInterestTags(experience) {
  if (!Array.isArray(experience?.interest_tags)) {
    return [];
  }
  return experience.interest_tags.filter(
    (tag) => typeof tag === 'string' && tag.trim().length > 0
  );
}

// Compatibilidad infantil de Paso 4: cada experiencia debe admitir al grupo completo.
function evaluateSpecializedPreferenceGroupCompatibility(
  preferenceId, experiences, tripChildren, tripChildrenAges, metadataStatus
) {
  const result = (status, reason, details = {}) => ({
    status, reason, age: null, minAge: null, maxAge: null, ...details,
  });
  if (!SPECIALIZED_OPT_IN_INTEREST_TAGS.has(preferenceId)) {
    return result('COMPATIBLE', 'NORMAL_PREFERENCE');
  }
  if (metadataStatus !== 'loaded' || !Array.isArray(experiences)) {
    return result('UNKNOWN', 'METADATA_UNAVAILABLE');
  }
  const associated = experiences.filter((experience) =>
    getExperienceInterestTags(experience).includes(preferenceId)
  );
  if (!associated.length) return result('UNKNOWN', 'NO_ASSOCIATED_EXPERIENCES');
  if (!Number.isInteger(tripChildren) || tripChildren < 0) {
    return result('UNKNOWN', 'PENDING_CHILD_AGES');
  }
  if (tripChildren === 0) return result('COMPATIBLE', 'NO_CHILDREN');
  const ages = Array.isArray(tripChildrenAges) ? tripChildrenAges : [];
  const validAge = (age) => typeof age === 'number' &&
    Number.isFinite(age) && age >= 0 && age <= 17;
  const knownAges = ages.slice(0, tripChildren).filter(validAge);
  const complete = ages.length === tripChildren && ages.every(validAge);
  // null es ausencia de límite; NaN conserva explícitamente datos inválidos.
  const normalizeLimit = (value) => {
    if (value === null) return null;
    if ((typeof value !== 'number' && typeof value !== 'string') ||
        (typeof value === 'string' && value.trim() === '')) return NaN;
    const number = Number(value);
    return Number.isFinite(number) && number >= 0 ? number : NaN;
  };
  const ranges = associated.map((experience) => {
    const min = normalizeLimit(experience.minimum_participant_age);
    const max = normalizeLimit(experience.maximum_participant_age);
    const valid = !Number.isNaN(min) && !Number.isNaN(max) &&
      !(min !== null && max !== null && min > max);
    const rejected = valid && knownAges.some((age) =>
      (min !== null && age < min) || (max !== null && age > max)
    );
    return { min, max, valid, rejected };
  });
  if (complete && ranges.some((range) => range.valid && !range.rejected)) {
    return result('COMPATIBLE', 'EXPERIENCE_SUPPORTS_GROUP');
  }
  if (!ranges.every((range) => range.rejected)) {
    return result('UNKNOWN', complete ? 'INVALID_AGE_LIMITS' : 'PENDING_CHILD_AGES');
  }
  // Explicación común únicamente si TODOS los límites la justifican.
  if (ranges.every((range) => range.min !== null)) {
    const minAge = Math.min(...ranges.map((range) => range.min));
    const age = knownAges.find((value) => value < minAge);
    if (age !== undefined) return result('INCOMPATIBLE', 'CHILD_BELOW_MINIMUM', { age, minAge });
  }
  if (ranges.every((range) => range.max !== null)) {
    const maxAge = Math.max(...ranges.map((range) => range.max));
    const age = knownAges.find((value) => value > maxAge);
    if (age !== undefined) return result('INCOMPATIBLE', 'CHILD_ABOVE_MAXIMUM', { age, maxAge });
  }
  return result('INCOMPATIBLE', 'NO_EXPERIENCE_SUPPORTS_GROUP');
}

// Metadatos informativos de Paso 4; no determina elegibilidad ni selección.
function getSpecializedPreferenceAgeMetadata(
  preferenceId,
  experiences,
  tripChildrenAges
) {
  const associated = (Array.isArray(experiences) ? experiences : [])
    .filter((experience) => getExperienceInterestTags(experience).includes(preferenceId));
  const minimums = associated.map((experience) => {
    const value = experience.minimum_participant_age;
    if ((typeof value !== 'number' && typeof value !== 'string') ||
        (typeof value === 'string' && value.trim() === '')) return null;
    const minimum = Number(value);
    return Number.isFinite(minimum) && minimum >= 0 ? minimum : null;
  });
  // No afirmar un mínimo común si alguna experiencia no lo registra.
  if (!minimums.length || minimums.some((age) => age === null)) return null;
  const minimumAges = [...new Set(minimums)];

  const minimumAge = Math.min(...minimumAges);
  const childrenBelowMinimumAge =
    (Array.isArray(tripChildrenAges) ? tripChildrenAges : []).filter(
      (age) => typeof age === 'number' && Number.isInteger(age) &&
        age >= 0 && age <= 17 && age < minimumAge
    );

  return {
    minimumAge,
    maximumMinimumAge: Math.max(...minimumAges),
    displayMode: minimumAges.length === 1 ? 'single' : 'variable',
    childrenBelowMinimumAge,
  };
}

// ANY-MATCH: basta con que el usuario haya seleccionado UNO de los
// tags especializados de la experiencia para permitir considerarla.
// No garantiza que entre al itinerario (edad/grupo/horario/etc. siguen).
function evaluateSpecializedExperiencePreference(
  experience,
  selectedPreferences
) {
  const interestTags = getExperienceInterestTags(experience);
  const specializedTags = interestTags.filter((tag) =>
    SPECIALIZED_OPT_IN_INTEREST_TAGS.has(tag)
  );
  const prefs = Array.isArray(selectedPreferences)
    ? selectedPreferences
    : [];

  if (specializedTags.length === 0) {
    return {
      allowed: true,
      interestTags,
      specializedTags,
      reason: 'NO_SPECIALIZED_TAGS',
    };
  }

  const matched = specializedTags.some((tag) => prefs.includes(tag));
  return {
    allowed: matched,
    interestTags,
    specializedTags,
    reason: matched
      ? 'SPECIALIZED_PREFERENCE_MATCH'
      : 'SPECIALIZED_PREFERENCE_NOT_SELECTED',
  };
}

function isExperienceAllowedBySpecializedPreferences(
  experience,
  selectedPreferences
) {
  return evaluateSpecializedExperiencePreference(
    experience,
    selectedPreferences
  ).allowed;
}

// Solo presentación: nombre de experiencia según idioma.
// No modifica activity.name ni identidad interna.
function getLocalizedExperienceName(
  activity,
  language,
  experienceNamesById = null
) {
  if (!activity || typeof activity !== 'object') {
    return '';
  }

  const isPresent = (value) =>
    typeof value === 'string' && value.trim().length > 0;

  const experienceId =
    activity?.experienceId ??
    activity?.experience_id ??
    (activity?.sourceType === 'EXPERIENCE'
      ? activity?.id ?? null
      : null);
  const catalogEntry =
    experienceId && experienceNamesById
      ? experienceNamesById[String(experienceId)] ?? null
      : null;

  const normalizedLanguage = normalizeLanguage(language);

  if (normalizedLanguage === 'en') {
    if (isPresent(activity.name_en)) {
      return activity.name_en.trim();
    }
    if (isPresent(catalogEntry?.name_en)) {
      return catalogEntry.name_en.trim();
    }
  }

  if (normalizedLanguage === 'es') {
    if (isPresent(activity.name_es)) {
      return activity.name_es.trim();
    }
    if (isPresent(catalogEntry?.name_es)) {
      return catalogEntry.name_es.trim();
    }
  }

  if (isPresent(activity.name)) {
    return activity.name.trim();
  }
  if (isPresent(catalogEntry?.name)) {
    return catalogEntry.name.trim();
  }

  return typeof activity.name === 'string' ? activity.name : '';
}

// Solo presentación: prioriza la descripción localizada disponible sin
// modificar la actividad persistida ni el snapshot del itinerario.
function getLocalizedItineraryExperienceDescription({
  activity,
  language,
  experienceDescriptionsById,
}) {
  const experienceId =
    activity?.experienceId ??
    activity?.experience_id ??
    (activity?.sourceType === 'EXPERIENCE'
      ? activity?.id ?? null
      : null);
  const catalogDescription = experienceId
    ? experienceDescriptionsById?.[String(experienceId)] ?? null
    : null;
  const normalizedLanguage = normalizeLanguage(language);
  const localizedDescription =
    normalizedLanguage === 'en'
      ? activity?.description_en ?? catalogDescription?.description_en
      : activity?.description_es ?? catalogDescription?.description_es;

  return (
    localizedDescription ??
    activity?.description ??
    catalogDescription?.description ??
    null
  );
}

// Solo presentación: traduce unidades estructuradas de tarifas dentro del
// itinerario sin modificar la tarifa original ni el snapshot persistido.
function getLocalizedItineraryPriceUnit(unit, language) {
  const normalizedUnit = String(unit ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();

  const unitKeyByValue = {
    persona: 'itinerary.priceUnit.person',
    person: 'itinerary.priceUnit.person',
    per_person: 'itinerary.priceUnit.person',
    entrada_persona: 'itinerary.priceUnit.person',
    noche_persona: 'itinerary.priceUnit.personNight',
    noche_habitacion: 'itinerary.priceUnit.roomNight',
    vehiculo_1_persona: 'itinerary.priceUnit.individualVehicle',
    vehiculo_2_personas: 'itinerary.priceUnit.vehicleForTwo',
    viaje: 'itinerary.priceUnit.trip',
    trayecto: 'itinerary.priceUnit.trip',
  };

  const translationKey = unitKeyByValue[normalizedUnit];
  return translationKey
    ? translate(language, translationKey)
    : String(unit ?? '');
}

function serializeGeneratedTripAccommodation(accommodation) {
  if (!accommodation || typeof accommodation !== 'object') {
    return null;
  }

  const latitude = Number(accommodation.latitude);
  const longitude = Number(accommodation.longitude);

  return {
    id: accommodation.id ?? null,
    name:
      typeof accommodation.name === 'string'
        ? accommodation.name
        : null,
    checkInTime:
      accommodation.checkInTime ||
      accommodation.check_in_time ||
      null,
    checkOutTime:
      accommodation.checkOutTime ||
      accommodation.check_out_time ||
      null,
    check_in_time:
      accommodation.check_in_time ||
      accommodation.checkInTime ||
      null,
    check_out_time:
      accommodation.check_out_time ||
      accommodation.checkOutTime ||
      null,
    latitude: Number.isFinite(latitude) ? latitude : null,
    longitude: Number.isFinite(longitude) ? longitude : null,
    address:
      typeof accommodation.address === 'string'
        ? accommodation.address
        : null,
    image_url:
      typeof accommodation.image_url === 'string'
        ? accommodation.image_url
        : null,
  };
}

