// Presentación únicamente: conserva desconocidos sin modificar el día persistido.
function getDayTravelPresentation(day, totalActivityMinutes) {
  const totalTravelMinutes = Number.isFinite(day?.totalTravelMinutes)
    ? day.totalTravelMinutes : null;
  const hasUnknownTravel = day?.hasUnknownTravel === true || totalTravelMinutes === null;
  const totalRealLoadMinutes = hasUnknownTravel
    ? null
    : Number.isFinite(day?.totalEstimatedMinutes)
      ? day.totalEstimatedMinutes
      : totalActivityMinutes + totalTravelMinutes;
  return { totalTravelMinutes, totalRealLoadMinutes, hasUnknownTravel };
}

// El resumen ya persiste la completitud calculada desde unknownDistanceSegmentCount.
// No altera el monto ni la fórmula; clasifica su cobertura para ambas vistas.
function getOwnVehicleFuelPresentationStatus(summary) {
  if (summary?.transportMode !== 'own_vehicle' ||
      !Number.isFinite(summary?.estimatedOwnVehicleFuelCost) ||
      summary.estimatedOwnVehicleFuelCost < 0) return 'UNAVAILABLE';
  if (summary.finalOwnVehicleDistanceIsComplete === true) return 'COMPLETE';
  return Number.isFinite(summary.finalOwnVehicleDistanceKm) &&
    summary.finalOwnVehicleDistanceKm > 0 ? 'PARTIAL' : 'UNAVAILABLE';
}

function calculateOwnVehicleFuelEstimate({
  distanceKm,
  fuelEfficiencyKmPerLiter,
  fuelPriceCrcPerLiter,
  usdCrcExchangeRate,
}) {
  const distanceIsValid =
    Number.isFinite(distanceKm) && distanceKm >= 0;
  const fuelEfficiencyIsValid =
    Number.isFinite(fuelEfficiencyKmPerLiter) &&
    fuelEfficiencyKmPerLiter > 0;
  const fuelPriceIsAvailable =
    Number.isFinite(fuelPriceCrcPerLiter) &&
    fuelPriceCrcPerLiter > 0;
  const exchangeRateIsAvailable =
    Number.isFinite(usdCrcExchangeRate) &&
    usdCrcExchangeRate > 0;

  const normalizedDistanceKm = distanceIsValid ? distanceKm : null;
  const normalizedFuelEfficiencyKmPerLiter = fuelEfficiencyIsValid
    ? fuelEfficiencyKmPerLiter
    : null;
  const normalizedFuelPriceCrcPerLiter = fuelPriceIsAvailable
    ? fuelPriceCrcPerLiter
    : null;
  const normalizedUsdCrcExchangeRate = exchangeRateIsAvailable
    ? usdCrcExchangeRate
    : null;

  const estimatedLiters =
    distanceIsValid && fuelEfficiencyIsValid
      ? distanceKm / fuelEfficiencyKmPerLiter
      : null;
  const estimatedFuelCostCrc =
    Number.isFinite(estimatedLiters) && fuelPriceIsAvailable
      ? estimatedLiters * fuelPriceCrcPerLiter
      : null;
  const estimatedFuelCostUsd =
    Number.isFinite(estimatedFuelCostCrc) && exchangeRateIsAvailable
      ? estimatedFuelCostCrc / usdCrcExchangeRate
      : null;

  let status = 'COMPLETE';

  if (!distanceIsValid) {
    status = 'INVALID_DISTANCE';
  } else if (!fuelEfficiencyIsValid) {
    status = 'INVALID_FUEL_EFFICIENCY';
  } else if (!fuelPriceIsAvailable) {
    status = 'FUEL_PRICE_PENDING';
  } else if (!exchangeRateIsAvailable) {
    status = 'EXCHANGE_RATE_PENDING';
  }

  return {
    distanceKm: normalizedDistanceKm,
    fuelEfficiencyKmPerLiter:
      normalizedFuelEfficiencyKmPerLiter,
    estimatedLiters,
    fuelPriceCrcPerLiter: normalizedFuelPriceCrcPerLiter,
    estimatedFuelCostCrc,
    usdCrcExchangeRate: normalizedUsdCrcExchangeRate,
    estimatedFuelCostUsd,
    distanceIsValid,
    fuelEfficiencyIsValid,
    fuelPriceIsAvailable,
    exchangeRateIsAvailable,
    estimateIsComplete: status === 'COMPLETE',
    status,
  };
}

