function guessImageContentType(uri) {
  const lower = (uri || '').toLowerCase();

  if (lower.includes('.png')) {
    return 'image/png';
  }

  if (lower.includes('.webp')) {
    return 'image/webp';
  }

  if (lower.includes('.heic')) {
    return 'image/heic';
  }

  return 'image/jpeg';
}

function guessImageExtension(contentType) {
  if (contentType === 'image/png') {
    return 'png';
  }

  if (contentType === 'image/webp') {
    return 'webp';
  }

  if (contentType === 'image/heic') {
    return 'heic';
  }

  return 'jpg';
}

async function uploadBusinessPhoto(userId, uri) {
  const contentType = guessImageContentType(uri);
  const extension = guessImageExtension(contentType);
  const path = `${userId}/${Date.now()}.${extension}`;

  const response = await fetch(uri);

  if (!response.ok) {
    throw new Error('No se pudo leer la fotografía seleccionada.');
  }

  const arrayBuffer = await response.arrayBuffer();

  const { error } = await supabase.storage
    .from('business-photos')
    .upload(path, arrayBuffer, {
      contentType,
      upsert: false,
    });

  if (error) {
    throw error;
  }

  const { data } = supabase.storage
    .from('business-photos')
    .getPublicUrl(path);

  return data.publicUrl;
}

async function resolveBusinessLocationFromGps() {
  try {
    const permission = await Location.requestForegroundPermissionsAsync();
    if (permission.status !== 'granted') {
      return { status: 'permission_denied', location: null };
    }

    const currentPosition = await Location.getCurrentPositionAsync({
      accuracy: Location.Accuracy.Balanced,
    });
    const latitude = currentPosition?.coords?.latitude;
    const longitude = currentPosition?.coords?.longitude;

    if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
      return { status: 'invalid_result', location: null };
    }

    return {
      status: 'resolved',
      location: {
        name: 'Mi ubicación actual',
        latitude,
        longitude,
      },
    };
  } catch (error) {
    return { status: 'error', location: null };
  }
}

async function resolveBusinessLocationFromQuery(query) {
  const normalizedQuery = String(query || '').trim();
  if (!normalizedQuery) {
    return { status: 'error', location: null };
  }

  if (Platform.OS === 'web') {
    return { status: 'unsupported', location: null };
  }

  try {
    if (Platform.OS === 'android') {
      const permission = await Location.requestForegroundPermissionsAsync();
      if (permission.status !== 'granted') {
        return { status: 'permission_denied', location: null };
      }
    }

    const results = await Location.geocodeAsync(normalizedQuery);
    if (!Array.isArray(results)) {
      return { status: 'invalid_result', location: null };
    }
    if (results.length === 0) {
      return { status: 'not_found', location: null };
    }

    const validCandidates = results
      .filter(
        (candidate) =>
          Number.isFinite(Number(candidate?.latitude)) &&
          Number.isFinite(Number(candidate?.longitude))
      )
      .map((candidate) => ({
        latitude: Number(candidate.latitude),
        longitude: Number(candidate.longitude),
      }));

    if (validCandidates.length === 0) {
      return { status: 'invalid_result', location: null };
    }
    if (validCandidates.length > 1) {
      return {
        status: 'ambiguous',
        location: null,
        candidates: validCandidates,
      };
    }

    const candidate = validCandidates[0];
    return {
      status: 'resolved',
      location: {
        name: normalizedQuery,
        latitude: candidate.latitude,
        longitude: candidate.longitude,
      },
    };
  } catch (error) {
    return { status: 'error', location: null };
  }
}

function getBusinessLocationStatusMessage(status) {
  switch (status) {
    case 'resolving':
      return 'Buscando ubicación…';
    case 'resolved':
      return 'Ubicación confirmada';
    case 'not_found':
      return 'No encontramos esa ubicación. Intenta escribir más detalles.';
    case 'ambiguous':
      return 'Encontramos varias ubicaciones. Agrega más detalles, por ejemplo La Fortuna, San Carlos, Costa Rica.';
    case 'permission_denied':
      return 'Necesitamos permiso de ubicación para usar tu posición actual. También puedes escribir la ubicación.';
    case 'unsupported':
      return 'La búsqueda de ubicación no está disponible en esta plataforma.';
    case 'invalid_result':
      return 'No pudimos interpretar la ubicación. Intenta con otra descripción.';
    case 'error':
      return 'No pudimos obtener la ubicación. Intenta nuevamente.';
    default:
      return '';
  }
}

function isResolvedBusinessLocation(location) {
  return (
    location &&
    typeof location === 'object' &&
    Number.isFinite(Number(location.latitude)) &&
    Number.isFinite(Number(location.longitude))
  );
}

function hasValidBusinessCoordinates(business) {
  const rawLat = business?.latitude;
  const rawLon = business?.longitude;
  if (
    rawLat === null ||
    rawLat === undefined ||
    rawLat === '' ||
    rawLon === null ||
    rawLon === undefined ||
    rawLon === ''
  ) {
    return false;
  }
  const lat = Number(rawLat);
  const lon = Number(rawLon);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
    return false;
  }
  if (lat < -90 || lat > 90 || lon < -180 || lon > 180) {
    return false;
  }
  return true;
}

function isBusinessReadyForVerification(business) {
  const nameOk =
    typeof business?.name === 'string' && business.name.trim().length > 0;
  const categoryOk =
    typeof business?.category === 'string' && business.category.trim().length > 0;
  return nameOk && categoryOk && hasValidBusinessCoordinates(business);
}


function generatePendingPhotoId() {
  return (
    'ph_' +
    Date.now().toString(36) +
    '_' +
    Math.random().toString(36).slice(2, 10) +
    Math.random().toString(36).slice(2, 10)
  );
}

function resolvePendingPhotoContentType({ uri, mimeType, fileName }) {
  const candidates = [
    mimeType,
    fileName,
    uri,
  ]
    .filter(Boolean)
    .map((value) => String(value).toLowerCase());

  for (const value of candidates) {
    if (
      value.includes('heic') ||
      value.includes('heif') ||
      value.includes('image/heic') ||
      value.includes('image/heif')
    ) {
      const error = new Error(
        'El formato HEIC/HEIF no está permitido. Usa JPEG, PNG o WEBP.'
      );
      error.code = 'unsupported_format';
      throw error;
    }
  }

  for (const value of candidates) {
    if (value.includes('image/png') || value.endsWith('.png')) {
      return { contentType: 'image/png', extension: 'png' };
    }
    if (value.includes('image/webp') || value.endsWith('.webp')) {
      return { contentType: 'image/webp', extension: 'webp' };
    }
    if (
      value.includes('image/jpeg') ||
      value.includes('image/jpg') ||
      value.endsWith('.jpg') ||
      value.endsWith('.jpeg')
    ) {
      return { contentType: 'image/jpeg', extension: 'jpg' };
    }
  }

  const error = new Error(
    'Formato no permitido. Solo se aceptan JPEG, PNG o WEBP.'
  );
  error.code = 'unsupported_format';
  throw error;
}

async function uploadPendingBusinessPhoto({
  userId,
  businessId,
  uri,
  mimeType,
  fileName,
  fileSize,
}) {
  if (!userId || !businessId || !uri) {
    throw new Error('Faltan datos para subir la fotografía.');
  }

  const maxBytes = 5 * 1024 * 1024;

  if (
    typeof fileSize === 'number' &&
    Number.isFinite(fileSize) &&
    fileSize > maxBytes
  ) {
    const error = new Error(
      'La fotografía supera el máximo de 5 MB.'
    );
    error.code = 'file_too_large';
    throw error;
  }

  const { contentType, extension } = resolvePendingPhotoContentType({
    uri,
    mimeType,
    fileName,
  });

  const response = await fetch(uri);

  if (!response.ok) {
    throw new Error('No se pudo leer la fotografía seleccionada.');
  }

  const arrayBuffer = await response.arrayBuffer();

  if (!arrayBuffer || arrayBuffer.byteLength <= 0) {
    throw new Error('La fotografía seleccionada está vacía.');
  }

  if (arrayBuffer.byteLength > maxBytes) {
    const error = new Error(
      'La fotografía supera el máximo de 5 MB.'
    );
    error.code = 'file_too_large';
    throw error;
  }

  const uniqueId = generatePendingPhotoId();
  const storagePath = `${userId}/${businessId}/${uniqueId}.${extension}`;

  const { error: uploadError } = await supabase.storage
    .from('business-photos-pending')
    .upload(storagePath, arrayBuffer, {
      contentType,
      upsert: false,
    });

  if (uploadError) {
    throw uploadError;
  }

  const { data: photoId, error: rpcError } = await supabase.rpc(
    'add_business_photo',
    {
      p_business_id: businessId,
      p_storage_path: storagePath,
      p_sort_order: 0,
    }
  );

  if (rpcError) {
    try {
      const { error: removeError } = await supabase.storage
        .from('business-photos-pending')
        .remove([storagePath]);

      if (removeError) {
        if (typeof __DEV__ !== 'undefined' && __DEV__) {
          console.log(
            'Fotos V1: cleanup Storage tras fallo RPC no completado'
          );
        }
      }
    } catch (cleanupError) {
      if (typeof __DEV__ !== 'undefined' && __DEV__) {
        console.log(
          'Fotos V1: error secundario en cleanup Storage'
        );
      }
    }

    throw rpcError;
  }

  return {
    photoId,
    storagePath,
  };
}


const openActivityMaps = async (activity) => {
  if (
    activity?.latitude === null ||
    activity?.latitude === undefined ||
    activity?.longitude === null ||
    activity?.longitude === undefined
  ) {
    Alert.alert(
      'Ubicación no disponible',
      'Esta actividad todavía no tiene coordenadas registradas.'
    );
    return;
  }

  const latitude = activity.latitude;
  const longitude = activity.longitude;

  const mapsUrl =
    "https://www.google.com/maps/search/?api=1&query=" +
    latitude +
    "," +
    longitude;

  try {
    const supported = await Linking.canOpenURL(mapsUrl);

    if (supported) {
      await Linking.openURL(mapsUrl);
    } else {
      Alert.alert(
        'Mapa no disponible',
        'No fue posible abrir el mapa.'
      );
    }
  } catch (error) {
    Alert.alert(
      'Error',
      'No fue posible abrir la ubicación.'
    );
  }
};
