function Login({ onLogin, onClose, signupAuthRevision = 0 }) {
  const [initialSignupAuthRevision] = useState(signupAuthRevision);

  useEffect(() => {
    if (signupAuthRevision !== initialSignupAuthRevision) {
      onLogin();
    }
  }, [signupAuthRevision, initialSignupAuthRevision, onLogin]);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState('login');

  const submitLogin = async () => {
    if (!email.trim() || !password) {
      setMessage('Ingresa tu correo y contraseña.');
      return;
    }

    try {
      setLoading(true);
      setMessage('Iniciando sesión...');

      const { data, error } =
        await supabase.auth.signInWithPassword({
          email: email.trim(),
          password,
        });

      if (error) {
        if (typeof __DEV__ !== 'undefined' && __DEV__) {
          console.log('Error Supabase:', error.message);
        }
        setMessage(error.message);
        return;
      }

      if (data?.session) {
        if (typeof __DEV__ !== 'undefined' && __DEV__) {
          console.log('Login exitoso');
        }

        setMessage('');
        onLogin();
      } else {
        setMessage(
          'No se pudo establecer la sesión.'
        );
      }
    } catch (error) {
      if (typeof __DEV__ !== 'undefined' && __DEV__) {
        console.log(
          'Error inesperado:',
          error
        );
      }

      setMessage(
        'Ocurrió un error al iniciar sesión.'
      );
    } finally {
      setLoading(false);
    }
  };

  const submitRegister = async () => {
    if (
      !email.trim() ||
      !password ||
      !confirmPassword
    ) {
      setMessage(
        'Completa todos los campos.'
      );
      return;
    }

    if (password.length < 6) {
      setMessage(
        'La contraseña debe tener al menos 6 caracteres.'
      );
      return;
    }

    if (password !== confirmPassword) {
      setMessage(
        'Las contraseñas no coinciden.'
      );
      return;
    }

    try {
      setLoading(true);
      setMessage('Creando cuenta...');

      const { data, error } =
        await supabase.auth.signUp({
          email: email.trim(),
          password,
          options: {
            emailRedirectTo: 'malekugo://auth-callback',
          },
        });

      if (error) {
        if (typeof __DEV__ !== 'undefined' && __DEV__) {
          console.log(
            'Error registro:',
            error.message
          );
        }

        setMessage(error.message);
        return;
      }

      if (data?.session) {
        setMessage(
          'Cuenta creada correctamente.'
        );

        onLogin();
      } else {
        setMessage(
          'Cuenta creada. Revisa tu correo para confirmar tu cuenta.'
        );

        setMode('login');
      }
    } catch (error) {
      if (typeof __DEV__ !== 'undefined' && __DEV__) {
        console.log(
          'Error inesperado:',
          error
        );
      }

      setMessage(
        'Ocurrió un error al crear la cuenta.'
      );
    } finally {
      setLoading(false);
    }
  };

  const submitForgotPassword = async () => {
    if (!email.trim()) {
      setMessage(
        'Ingresa tu correo electrónico.'
      );
      return;
    }

    try {
      setLoading(true);
      setMessage('Enviando correo...');

      const { error } =
        await supabase.auth.resetPasswordForEmail(
          email.trim(),
          {
            redirectTo: 'malekugo://reset-password',
          }
        );

      if (error) {
        if (typeof __DEV__ !== 'undefined' && __DEV__) {
          console.log(
            'Error recuperación:',
            error.message
          );
        }

        setMessage(error.message);
        return;
      }

      setMessage(
        'Te enviamos un correo para recuperar tu contraseña.'
      );
    } catch (error) {
      if (typeof __DEV__ !== 'undefined' && __DEV__) {
        console.log(
          'Error inesperado:',
          error
        );
      }

      setMessage(
        'No se pudo enviar el correo de recuperación.'
      );
    } finally {
      setLoading(false);
    }
  };

  const title =
    mode === 'register'
      ? 'Crear una cuenta'
      : mode === 'forgot'
      ? 'Recuperar contraseña'
      : (
          <>
            ¡Bienvenido a Maleku Go{`\n`}
            Guide!
          </>
        );

  const buttonTitle =
    mode === 'register'
      ? loading
        ? 'Creando cuenta...'
        : 'Crear cuenta'
      : mode === 'forgot'
      ? loading
        ? 'Enviando...'
        : 'Enviar correo'
      : loading
      ? 'Iniciando sesión...'
      : 'Iniciar sesión';

  const submit =
    mode === 'register'
      ? submitRegister
      : mode === 'forgot'
      ? submitForgotPassword
      : submitLogin;

  return (
    <ImageBackground
      source={{ uri: hero }}
      style={styles.loginBg}
    >
      <View style={styles.darkOverlay} />

      <SafeAreaView style={styles.loginWrap}>
        <Pressable
          onPress={() => {
            if (mode !== 'login') {
              setMode('login');
              setMessage('');
            } else if (typeof onClose === 'function') {
              onClose();
            }
          }}
        >
          <Text style={styles.back}>‹</Text>
        </Pressable>

        <View style={styles.loginBody}>
          <Text style={styles.loginTitle}>
            {title}
          </Text>

          <Text style={styles.subtitle}>
            {mode === 'register'
              ? 'Crea tu cuenta y comienza a descubrir Costa Rica'
              : mode === 'forgot'
              ? 'Te ayudaremos a recuperar el acceso a tu cuenta'
              : 'Descubre Costa Rica como nunca antes'}
          </Text>

          <Text style={styles.label}>
            CORREO ELECTRÓNICO
          </Text>

          <TextInput
            value={email}
            onChangeText={(text) => {
              setEmail(text);
              setMessage('');
            }}
            style={styles.input}
            placeholder="Correo electrónico"
            placeholderTextColor={colors.muted}
            keyboardType="email-address"
            autoCapitalize="none"
            autoCorrect={false}
          />

          {mode !== 'forgot' && (
            <>
              <Text style={styles.label}>
                CONTRASEÑA
              </Text>

              <TextInput
                value={password}
                onChangeText={(text) => {
                  setPassword(text);
                  setMessage('');
                }}
                style={styles.input}
                placeholder="Contraseña"
                placeholderTextColor={colors.muted}
                secureTextEntry
              />
            </>
          )}

          {mode === 'register' && (
            <>
              <Text style={styles.label}>
                CONFIRMAR CONTRASEÑA
              </Text>

              <TextInput
                value={confirmPassword}
                onChangeText={(text) => {
                  setConfirmPassword(text);
                  setMessage('');
                }}
                style={styles.input}
                placeholder="Repite tu contraseña"
                placeholderTextColor={colors.muted}
                secureTextEntry
              />
            </>
          )}

          <Button
            title={buttonTitle}
            onPress={submit}
            disabled={loading}
          />

          {!!message && (
            <Text style={styles.help}>
              {message}
            </Text>
          )}

          {mode === 'login' && (
            <>
              <Pressable
                onPress={() => {
                  setMode('register');
                  setMessage('');
                }}
              >
                <Text style={styles.help}>
                  ¿No tienes cuenta?{' '}
                  <Text style={styles.goldText}>
                    Regístrate aquí
                  </Text>
                </Text>
              </Pressable>

              <Pressable
                onPress={() => {
                  setMode('forgot');
                  setMessage('');
                }}
              >
                <Text style={styles.help}>
                  ¿Olvidaste tu contraseña?
                </Text>
              </Pressable>
            </>
          )}

          {mode === 'register' && (
            <Pressable
              onPress={() => {
                setMode('login');
                setMessage('');
              }}
            >
              <Text style={styles.help}>
                ¿Ya tienes una cuenta?{' '}
                <Text style={styles.goldText}>
                  Inicia sesión
                </Text>
              </Text>
            </Pressable>
          )}

          {mode === 'forgot' && (
            <Pressable
              onPress={() => {
                setMode('login');
                setMessage('');
              }}
            >
              <Text style={styles.help}>
                Volver a iniciar sesión
              </Text>
            </Pressable>
          )}
        </View>
      </SafeAreaView>
    </ImageBackground>
  );
}

