/* =========================================================
   DETALLE DEL NEGOCIO
   ========================================================= */

function BusinessDetail({
  place,
  onClose,
  t,
  language,
}) {
  const [isFavorite, setIsFavorite] = useState(false);
  const [favoriteLoading, setFavoriteLoading] = useState(false);

  const location = [
    place.district,
    place.canton,
    place.province,
  ]
    .filter(Boolean)
    .join(' • ');
  const descriptionCandidates =
    normalizeLanguage(language) === 'en'
      ? [
          place?.description_en,
          place?.description,
          place?.description_es,
        ]
      : [
          place?.description_es,
          place?.description,
          place?.description_en,
        ];
  const localizedDescription =
    descriptionCandidates.find(
      (description) =>
        typeof description === 'string' &&
        description.trim().length > 0
    ) ?? null;
  const normalizedBudgetLevel = String(
    place?.budget_level ?? ''
  )
    .trim()
    .toLowerCase();
  const localizedBudgetLevel =
    normalizedBudgetLevel === 'premium'
      ? `💎 ${t('planner.budget.premium')}`
      : normalizedBudgetLevel === 'medio'
        ? `💰 ${t('planner.budget.medium')}`
        : normalizedBudgetLevel === 'bajo'
          ? `💵 ${t('planner.budget.low')}`
          : normalizedBudgetLevel
            ? place.budget_level
            : t('businessDetail.budget.undefined');

  useEffect(() => {
    let mounted = true;

    const checkFavorite = async () => {
      if (!place?.id) {
        return;
      }

      const {
        data: { user },
        error: userError,
      } = await supabase.auth.getUser();

      if (userError || !user) {
        if (mounted) {
          setIsFavorite(false);
        }
        return;
      }

      if (typeof __DEV__ !== 'undefined' && __DEV__) {
        console.log("=== ANTES DE CONSULTAR BUSINESSES ===");
      }

      const { data, error } = await supabase
        .from('favorites')
        .select('id')
        .eq('user_id', user.id)
        .eq('business_id', place.id)
        .maybeSingle();

      if (!mounted) {
        return;
      }

      if (error) {
        if (typeof __DEV__ !== 'undefined' && __DEV__) {
          console.log(
            'Error comprobando favorito:',
            error.message
          );
        console.log("=== DESPUES DE CONSULTAR BUSINESSES ===");
        console.log("Cantidad de negocios:", data?.length ?? 0);
        console.log("Error Supabase:", error?.message ?? "NINGUNO");
        }

        setIsFavorite(false);
        return;
      }

      setIsFavorite(!!data);
    };

    checkFavorite();

    return () => {
      mounted = false;
    };
  }, [place?.id]);

  const toggleFavorite = async () => {
    if (!place?.id || favoriteLoading) {
      return;
    }

    setFavoriteLoading(true);

    try {
      const {
        data: { user },
        error: userError,
      } = await supabase.auth.getUser();

      if (userError || !user) {
        Alert.alert(
          t('businessDetail.alert.sessionRequiredTitle'),
          t('businessDetail.alert.sessionRequiredMessage')
        );
        return;
      }

      if (isFavorite) {
        const { error } = await supabase
          .from('favorites')
          .delete()
          .eq('user_id', user.id)
          .eq('business_id', place.id);

        if (error) {
          if (typeof __DEV__ !== 'undefined' && __DEV__) {
            console.log(
              'Error eliminando favorito:',
              error.message
            );
          }

          Alert.alert(
            t('businessDetail.alert.errorTitle'),
            t('businessDetail.alert.favoriteRemoveError')
          );
          return;
        }

        setIsFavorite(false);
      } else {
        const { error } = await supabase
          .from('favorites')
          .insert({
            user_id: user.id,
            business_id: place.id,
          });

        if (error) {
          if (typeof __DEV__ !== 'undefined' && __DEV__) {
            console.log(
              'Error agregando favorito:',
              error.message
            );
          }

          Alert.alert(
            t('businessDetail.alert.errorTitle'),
            t('businessDetail.alert.favoriteSaveError')
          );
          return;
        }

        setIsFavorite(true);
      }
    } catch (error) {
      if (typeof __DEV__ !== 'undefined' && __DEV__) {
        console.log(
          'Error inesperado con favorito:',
          error
        );
      }

      Alert.alert(
        t('businessDetail.alert.errorTitle'),
        t('businessDetail.alert.favoriteUnexpectedError')
      );
    } finally {
      setFavoriteLoading(false);
    }
  };

  const openWhatsApp = async () => {
    if (!place.phone) {
      return;
    }

    const phone = place.phone.replace(/[^\d]/g, '');
    const whatsappUrl = "https://wa.me/" + phone;

    try {
      const supported = await Linking.canOpenURL(whatsappUrl);

      if (supported) {
        await Linking.openURL(whatsappUrl);
      } else {
        Alert.alert(
          t('businessDetail.alert.whatsAppUnavailableTitle'),
          t('businessDetail.alert.whatsAppUnavailableMessage')
        );
      }
    } catch (error) {
      Alert.alert(
        t('businessDetail.alert.errorTitle'),
        t('businessDetail.alert.whatsAppUnavailableMessage')
      );
    }
  };
  const openMaps = async () => {
    if (
      place.latitude === null ||
      place.latitude === undefined ||
      place.longitude === null ||
      place.longitude === undefined
    ) {
      Alert.alert(
        t('businessDetail.alert.locationUnavailableTitle'),
        t('businessDetail.alert.locationUnavailableMessage')
      );
      return;
    }

    const latitude = place.latitude;
    const longitude = place.longitude;

    const mapsUrl =
      "https://www.google.com/maps/search/?api=1&query=" +
      latitude +
      "," +
      longitude;

    try {
      const supported = await Linking.canOpenURL(mapsUrl);

      if (supported) {
        await Linking.openURL(mapsUrl);
      } else {
        Alert.alert(
          t('businessDetail.alert.mapUnavailableTitle'),
          t('businessDetail.alert.mapUnavailableMessage')
        );
      }
    } catch (error) {
      Alert.alert(
        t('businessDetail.alert.errorTitle'),
        t('businessDetail.alert.locationOpenError')
      );
    }
  };
  const openWebsite = async () => {
    if (!place.website) {
      return;
    }

    let websiteUrl = place.website.trim();

    if (
      !websiteUrl.startsWith('http://') &&
      !websiteUrl.startsWith('https://')
    ) {
      websiteUrl = 'https://' + websiteUrl;
    }

    try {
      const supported = await Linking.canOpenURL(websiteUrl);

      if (supported) {
        await Linking.openURL(websiteUrl);
      } else {
        Alert.alert(
          t('businessDetail.alert.websiteUnavailableTitle'),
          t('businessDetail.alert.websiteUnavailableMessage')
        );
      }
    } catch (error) {
      Alert.alert(
        t('businessDetail.alert.errorTitle'),
        t('businessDetail.alert.websiteUnavailableMessage')
      );
    }
  };
  const callBusiness = async () => {
    if (!place.phone) {
      return;
    }
    const phoneUrl = "tel:" + place.phone;

    try {
      const supported = await Linking.canOpenURL(phoneUrl);

      if (supported) {
        await Linking.openURL(phoneUrl);
      } else {
        Alert.alert(
          t('businessDetail.alert.phoneUnavailableTitle'),
          t('businessDetail.alert.phoneUnavailableMessage')
        );
      }
    } catch (error) {
      Alert.alert(
        t('businessDetail.alert.errorTitle'),
        t('businessDetail.alert.phoneCallError')
      );
    }
  };

  return (
    <ImageBackground
  source={require('./assets/fondo-volcan-arenal.png')}
  style={styles.home}
  imageStyle={{ opacity: 0.55 }}
>
  <StatusBar barStyle="dark-content" />
  <SafeAreaView style={styles.home}>
      <ScrollView
        contentContainerStyle={styles.homeScroll}
        showsVerticalScrollIndicator={false}
      >
        <Pressable
          onPress={onClose}
          style={styles.detailBackButton}
        >
          <Text style={styles.detailBackText}>
            {t('common.back')}
          </Text>
        </Pressable>

        <ImageBackground
          source={
            place.image_url
              ? { uri: place.image_url }
              : { uri: hero }
          }
          style={styles.detailImage}
        >
          <View style={styles.detailImageOverlay}>
            <Text style={styles.cardLabel}>
              {getLocalizedBusinessDetailCategory(place.category, t)}
            </Text>
          </View>
        </ImageBackground>

        <Text style={styles.detailTitle}>
          {place.name || t('businessDetail.unknownBusiness')}
        </Text>

        <Text style={styles.detailBudget}>
          {localizedBudgetLevel}
        </Text>

        <Pressable
          onPress={toggleFavorite}
          disabled={favoriteLoading}
          style={[
            styles.favoriteButton,
            isFavorite && styles.favoriteButtonActive,
          ]}
        >
          <Text style={styles.favoriteButtonIcon}>
            {isFavorite ? '❤️' : '🤍'}
          </Text>

          <Text style={styles.favoriteButtonText}>
            {favoriteLoading
              ? t('businessDetail.favorite.saving')
              : isFavorite
              ? t('businessDetail.favorite.saved')
              : t('businessDetail.favorite.add')}
          </Text>
        </Pressable>

        {localizedDescription ? (
          <Text style={styles.detailDescription}>
            {localizedDescription}
          </Text>
        ) : (
          <Text style={styles.detailDescription}>
            {t('businessDetail.descriptionFallback')}
          </Text>
        )}

        {location ? (
          <View style={styles.detailInfoBox}>
            <Text style={styles.detailInfoLabel}>
              📍 {t('businessDetail.location')}
            </Text>

            <Text style={styles.detailInfoText}>
              {location}
            </Text>

            {place.address ? (
              <Text style={styles.detailInfoSecondary}>
                {place.address}
              </Text>
            ) : null}
          </View>
        ) : null}

        {(place.latitude !== null &&
          place.latitude !== undefined &&
          place.longitude !== null &&
          place.longitude !== undefined) ? (
          <Pressable
            onPress={openMaps}
            style={styles.detailInfoBox}
          >
            <Text style={styles.detailInfoLabel}>
              🗺️ {t('businessDetail.directions')}
            </Text>

            <Text style={styles.detailInfoText}>
              {t('businessDetail.openInMaps')}
            </Text>

            <Text style={styles.detailActionText}>
              {t('businessDetail.viewRoute')}
            </Text>
          </Pressable>
        ) : null}

        {place.phone ? (
          <Pressable
            onPress={callBusiness}
            style={styles.detailInfoBox}
          >
            <Text style={styles.detailInfoLabel}>
              📞 {t('businessDetail.phone')}
            </Text>

            <Text style={styles.detailInfoText}>
              {place.phone}
            </Text>

            <Text style={styles.detailActionText}>
              {t('businessDetail.call')}
            </Text>
          </Pressable>
        ) : null}

        {place.phone ? (
          <Pressable
            onPress={openWhatsApp}
            style={styles.detailInfoBox}
          >
            <Text style={styles.detailInfoLabel}>
              💬 {t('businessDetail.whatsApp')}
            </Text>

            <Text style={styles.detailInfoText}>
              {t('businessDetail.contactBusiness')}
            </Text>

            <Text style={styles.detailActionText}>
              {t('businessDetail.openWhatsApp')}
            </Text>
          </Pressable>
        ) : null}
        {place.website ? (
          <Pressable
            onPress={openWebsite}
            style={styles.detailInfoBox}
          >
            <Text style={styles.detailInfoLabel}>
              🌐 {t('businessDetail.website')}
            </Text>

            <Text style={styles.detailInfoText}>
              {place.website}
            </Text>

            <Text style={styles.detailActionText}>
              {t('businessDetail.visit')}
            </Text>
          </Pressable>
        ) : null}
      </ScrollView>
    </SafeAreaView>
    </ImageBackground>
  );
}
