  const resolveTripOriginFromCurrentLocation = async () => {
    markTripDraftProgress();
    setTripOriginMode('current_location');
    setTripOriginResolutionStatus('resolving');
    setTripOriginLocation(null);

    try {
      const permission =
        await Location.requestForegroundPermissionsAsync();

      if (permission.status !== 'granted') {
        setTripOriginResolutionStatus('error');
        return null;
      }

      const currentPosition =
        await Location.getCurrentPositionAsync({
          accuracy: Location.Accuracy.Balanced,
        });
      const latitude = currentPosition?.coords?.latitude;
      const longitude = currentPosition?.coords?.longitude;

      if (
        !Number.isFinite(latitude) ||
        !Number.isFinite(longitude)
      ) {
        setTripOriginLocation(null);
        setTripOriginResolutionStatus('error');
        return null;
      }

      const resolvedLocation = {
        name: 'Mi ubicación actual',
        latitude,
        longitude,
      };

      setTripOriginLocation(resolvedLocation);
      setTripOriginResolutionStatus('resolved');

      if (typeof __DEV__ !== 'undefined' && __DEV__) {
        console.log('=== TRIP ORIGIN GPS RESOLVED ===');
      }

      return resolvedLocation;
    } catch (error) {
      console.error('Error resolving current trip origin location:');
      setTripOriginLocation(null);
      setTripOriginResolutionStatus('error');

      return null;
    }
  };

  const resolveLocationQuery = async ({
    query,
    setLocation,
    setResolutionStatus,
  }) => {
    const normalizedQuery = String(query || '').trim();

    if (!normalizedQuery) {
      setLocation(null);
      setResolutionStatus('error');
      return null;
    }

    if (Platform.OS === 'web') {
      setLocation(null);
      setResolutionStatus('unsupported');
      return null;
    }

    setResolutionStatus('resolving');
    setLocation(null);

    try {
      if (Platform.OS === 'android') {
        const permission =
          await Location.requestForegroundPermissionsAsync();

        if (permission.status !== 'granted') {
          setLocation(null);
          setResolutionStatus('permission_denied');
          return null;
        }
      }

      const results = await Location.geocodeAsync(normalizedQuery);

      if (!Array.isArray(results)) {
        setLocation(null);
        setResolutionStatus('invalid_result');
        return null;
      }

      if (results.length === 0) {
        setLocation(null);
        setResolutionStatus('not_found');
        return null;
      }

      const validCandidates = results
        .filter(
          (candidate) =>
            Number.isFinite(Number(candidate?.latitude)) &&
            Number.isFinite(Number(candidate?.longitude))
        )
        .map((candidate) => ({
          latitude: Number(candidate.latitude),
          longitude: Number(candidate.longitude),
          altitude: candidate?.altitude,
          accuracy: candidate?.accuracy,
        }));

      if (validCandidates.length === 0) {
        setLocation(null);
        setResolutionStatus('invalid_result');
        return null;
      }

      if (validCandidates.length > 1) {
        setLocation(null);
        setResolutionStatus('ambiguous');
        return {
          status: 'ambiguous',
          query: normalizedQuery,
          candidates: validCandidates,
        };
      }

      const candidate = validCandidates[0];
      const resolvedLocation = {
        name: normalizedQuery,
        latitude: candidate.latitude,
        longitude: candidate.longitude,
      };

      setLocation(resolvedLocation);
      setResolutionStatus('resolved');

      return resolvedLocation;
    } catch (error) {
      console.error('Error resolving location query:');
      setLocation(null);
      setResolutionStatus('error');

      return null;
    }
  };

