  const getTripBudgetProfile = ({
    maximumBudget,
    totalPeople,
    totalDays,
  }) => {
    const parsedMaximumBudget = Number(maximumBudget);
    const parsedTotalPeople = Number(totalPeople);
    const parsedTotalDays = Number(totalDays);

    if (
      !Number.isFinite(parsedMaximumBudget) ||
      parsedMaximumBudget <= 0 ||
      !Number.isFinite(parsedTotalPeople) ||
      parsedTotalPeople <= 0 ||
      !Number.isFinite(parsedTotalDays) ||
      parsedTotalDays <= 0
    ) {
      return {
        id: null,
        label: 'Sin clasificar',
        amountPerPersonPerDay: null,
      };
    }

    const amountPerPersonPerDay =
      parsedMaximumBudget /
      parsedTotalPeople /
      parsedTotalDays;

    if (amountPerPersonPerDay <= 60) {
      return {
        id: 'bajo',
        label: 'Económico',
        amountPerPersonPerDay,
      };
    }

    if (amountPerPersonPerDay <= 140) {
      return {
        id: 'medio',
        label: 'Equilibrado',
        amountPerPersonPerDay,
      };
    }

    return {
      id: 'premium',
      label: 'Premium',
      amountPerPersonPerDay,
    };
  };

