          providerName: business?.name || null,
          name: experience?.name || null,
          name_es: experience?.name_es ?? null,
          name_en: experience?.name_en ?? null,
          description: experience?.description ?? null,
          description_es: experience?.description_es ?? null,
          description_en: experience?.description_en ?? null,
          category:
            experience?.category || business?.category || null,
          experience_type:
            experience?.experience_type ?? null,
          date,
          dayNumber,
          weekday: session?.weekday ?? null,
          sessionId: session?.id || null,
          startTime: logisticsEvaluation.startTime,
          endTime: logisticsEvaluation.endTime,
          durationMinutes: Number.isFinite(durationMinutes)
            ? durationMinutes
            : null,
          estimatedHours: Number.isFinite(durationMinutes)
            ? durationMinutes / 60
            : null,
          latitude:
            experience?.latitude ?? business?.latitude ?? null,
          longitude:
            experience?.longitude ?? business?.longitude ?? null,
          requires_reservation:
            experience?.requires_reservation ?? null,
          is_bookable: experience?.is_bookable ?? null,
          bookingUrl: experience?.booking_url || null,
          whatsapp: experience?.whatsapp || null,
          phone: business?.phone || null,
          experience_rates: activeRates,
          displayRateTotal: Number.isFinite(rateResult?.total)
