                    route?.destination_business_id ?? null;
                  const idMatch =
                    routeOriginBusinessId === segmentFromBusinessId &&
                    routeDestinationBusinessId === segmentToBusinessId;
                  const nameMatch =
                    normalizeText(route?.origin_name) === segmentFrom &&
                    normalizeText(route?.destination_name) === segmentTo;
                  const normalizedUnit = normalizeText(
                    route?.price_unit
                  );
                  const numericPrice = Number(route?.price);
                  const minPeople = Number(route?.min_people);
                  const maxPeople = Number(route?.max_people);
                  const included = route?.is_included === true;
